<script setup>
import {ref,computed,nextTick,onBeforeUnmount} from 'vue';import ActionIcon from './ActionIcon.vue';
const props=defineProps({modelValue:[String,Number],options:{type:Array,default:()=>[]},label:String,placeholder:{type:String,default:'请选择'},disabled:Boolean});const emit=defineEmits(['update:modelValue','change','open']);const open=ref(false),trigger=ref(),popup=ref(),host=ref('body'),query=ref(''),pos=ref({}),active=ref(0);
const selected=computed(()=>props.options.find(o=>String(o.value)===String(props.modelValue))),visible=computed(()=>props.options.filter(o=>o.label.toLowerCase().includes(query.value.toLowerCase())));
function close(){open.value=false;document.removeEventListener('pointerdown',outside,true);window.removeEventListener('resize',close);document.removeEventListener('scroll',scroll,true)}
function outside(e){if(!trigger.value?.contains(e.target)&&!popup.value?.contains(e.target))close()}function scroll(e){if(!popup.value?.contains(e.target))close()}
async function toggle(){if(open.value){close();return}if(props.disabled)return;emit('open');query.value='';host.value=trigger.value.closest('dialog')||document.body;const r=trigger.value.getBoundingClientRect(),below=innerHeight-r.bottom,flip=below<220&&r.top>below;pos.value={left:Math.max(10,Math.min(r.left,innerWidth-r.width-10))+'px',width:r.width+'px',maxHeight:Math.min(300,Math.max(100,flip?r.top-20:below-15))+'px',...(flip?{bottom:innerHeight-r.top+4+'px'}:{top:r.bottom+4+'px'})};open.value=true;active.value=Math.max(0,visible.value.findIndex(o=>o.value===props.modelValue));document.addEventListener('pointerdown',outside,true);window.addEventListener('resize',close);document.addEventListener('scroll',scroll,true);await nextTick();popup.value?.focus()}
function choose(o){if(!o||o.disabled)return;emit('update:modelValue',o.value);emit('change',o.value);close();trigger.value.focus()}
function key(e){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();trigger.value.focus()}else if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(!open.value){toggle();return}let i=active.value;for(let n=0;n<visible.value.length;n++){i=(i+(e.key==='ArrowDown'?1:-1)+visible.value.length)%visible.value.length;if(!visible.value[i].disabled){active.value=i;break}}}else if(e.key==='Enter'||e.key===' '&&e.target.tagName!=='INPUT'){e.preventDefault();if(!open.value)toggle();else if(visible.value[active.value])choose(visible.value[active.value])}else if(e.key==='Tab')close()}
onBeforeUnmount(close);
</script>
<template><div class="icon-select"><button ref="trigger" type="button" role="combobox" :aria-label="label" :aria-expanded="open" :disabled="disabled" class="icon-select-trigger" @click="toggle" @keydown="key"><ActionIcon v-if="selected?.value" :action="{image:selected.image,icon:selected.icon||'Plugin'}" :size="20"/><span :class="{placeholder:!selected?.value}">{{selected?.label||placeholder}}</span><span aria-hidden="true">⌄</span></button><select class="icon-select-native" tabindex="-1" aria-hidden="true" :aria-label="label+'原生选项'" :value="modelValue" :disabled="disabled" @change="choose(options.find(o=>String(o.value)===$event.target.value))"><option v-if="!selected" value="">{{placeholder}}</option><option v-for="o in options" :key="o.value" :value="o.value" :disabled="o.disabled">{{o.label}}</option></select><Teleport :to="host"><div v-if="open" ref="popup" class="icon-select-popup" tabindex="-1" :style="pos" @keydown="key"><input v-if="options.length>8" v-model="query" :aria-label="'搜索'+label" placeholder="搜索"><div role="listbox" :aria-label="label+'列表'"><button v-for="(o,i) in visible" :key="o.value" type="button" role="option" :aria-selected="String(o.value)===String(modelValue)" :disabled="o.disabled" :class="{active:active===i}" @pointermove="active=i" @click="choose(o)"><ActionIcon v-if="o.value" :action="{image:o.image,icon:o.icon||'Plugin'}" :size="21"/><span>{{o.label}}</span></button><small v-if="!visible.length">没有匹配项</small></div></div></Teleport></div></template>
